  "faits": "L'explosion de la machine à vapeur du remorqueur Marie, due à un vice de construction, tue Teffaine ; sa veuve et ses enfants agissent contre les propriétaires du remorqueur.",
  "question": "Le propriétaire d'une chose dont le vice de construction a causé un décès peut-il être tenu envers la victime sans faute prouvée ?",
  "solution": "Le propriétaire du remorqueur est responsable envers la victime sur le fondement de l'art. 1384 : il ne peut échapper à cette responsabilité en invoquant la faute du constructeur ni le caractère caché du vice. Arrêt fondateur du principe général de responsabilité du fait des choses, d'abord appliqué à une chose dotée d'un vice.",
  "justifie": [
   {
    "argument": "Soutenir que l'art. 1384, al. 1er n'est pas une simple annonce des alinéas suivants mais pose un principe de responsabilité du fait des choses.",
    "ou": "Dissertation ou commentaire sur la genèse du principe général."
   },
   {
    "argument": "Écarter l'argument du propriétaire qui invoque la faute du constructeur ou le vice caché : seule la cause étrangère l'exonère.",
    "ou": "Cas pratique : chose défectueuse, recours de la victime contre le propriétaire."
   },
   {
    "argument": "Montrer que la jurisprudence a construit le régime pour répondre aux accidents industriels que l'art. 1382 (faute à prouver) indemnisait mal.",
    "ou": "Dissertation : justification historique du régime, lien avec la loi du 9 avril 1898."
   }
  ],
  "distinguer": "Ne pas le confondre avec Jand'heur (1930), qui étend le principe aux choses sans vice, actionnées par l'homme, et précise le régime d'exonération.",
