  "solution": "L'armateur n'avait pas perdu les pouvoirs de garde, et le fait de l'équipage, issu d'un conflit interne à l'entreprise, n'était pas une cause extérieure. Les mesures annoncées étaient prévisibles et il n'avait pas exercé toutes les voies de droit : ni fait de tiers ni force majeure ; rejet du pourvoi.",
  "justifie": [
   {
    "argument": "Soutenir que le fait des membres de l'équipage, issu d'un conflit interne à l'entreprise, n'est pas un fait de tiers exonératoire pour l'armateur.",
    "ou": "Cas pratique (fait de tiers, extériorité)"
   },
   {
    "argument": "Affirmer qu'un événement annoncé et que le gardien pouvait combattre n'est ni imprévisible ni irrésistible.",
    "ou": "Force majeure, cas pratique"
   }
  ],
  "distinguer": "Ne pas dire que le fait d'un groupe de personnes est toujours un fait de tiers : tout dépend de leur lien avec le gardien et de la prévisibilité de l'événement.",
