  "juridiction": "Civ. 2e",
  "date": "1996-02-28",
  "numero": "93-20817",
  "provenance": [
   "CM"
  ],
  "chapitres": [
   14
  ],
  "notions": [
   "transfert de garde",
   "magasin libre-service",
   "garde"
  ],
  "faits": "Dans un magasin Continent en libre-service, une cliente inconnue fait tomber une bouteille qui éclate et blesse Mme X. par des éclats de verre ; celle-ci assigne le magasin.",
  "question": "La manipulation d'un objet par un client d'un libre-service transfère-t-elle la garde de cet objet ?",
  "solution": "Rejet : dans un magasin où la clientèle se sert elle-même, la simple manipulation d'un objet offert à la vente ne suffit pas à transférer la garde ; le magasin reste gardien de la bouteille et responsable.",
  "justifie": [
   {
    "argument": "Soutenir que le magasin libre-service reste gardien des produits qu'un client manipule et fait tomber.",
    "ou": "Cas pratique : chute d'un objet de rayon, accident en grande surface."
   },
   {
    "argument": "Rappeler que la garde ne se transfère que si le détenteur reçoit les pouvoirs d'usage, de direction et de contrôle, non par une simple manipulation.",
    "ou": "Transfert de garde."
   }
  ],
  "distinguer": "À rapprocher de 14 janv. 1999 (chariot confié à un client) : solutions variables selon la chose, la durée et les circonstances.",
  "textes": [
   "1384 al. 1er (ancien)",
   "1242 al. 1er"
  ],
