  "numero": "99-13.701",
  "provenance": [
   "CM"
  ],
  "chapitres": [
   17
  ],
  "notions": [
   "préjudice légitime",
   "naissance d'un enfant handicapé",
   "loi anti-Perruche",
   "causalité"
  ],
  "faits": "Une femme enceinte, dont le médecin et le laboratoire se trompent dans la recherche des anticorps de la rubéole, croit être immunisée ; elle aurait recouru à l'IVG en cas d'atteinte. L'enfant naît gravement handicapé.",
  "question": "L'enfant né handicapé peut-il demander réparation du préjudice résultant de son handicap lorsque les fautes médicales ont privé sa mère du choix d'interrompre la grossesse ?",
  "solution": "Oui : dès lors que les fautes ont empêché la mère d'exercer ce choix, l'enfant peut demander la réparation du préjudice résultant de son handicap et causé par ces fautes. Cassation de l'arrêt de renvoi. La loi du 4 mars 2002 a écarté cette solution.",
  "justifie": [
   {
    "argument": "Rappeler que l'Assemblée plénière avait admis en 2000 le préjudice de l'enfant né handicapé, lien causal avec les fautes ayant privé la mère de son choix.",
    "ou": "Dissertation ou commentaire sur le préjudice résultant de la naissance"
   },
   {
    "argument": "Expliquer la loi dite « anti-Perruche » (CASF, art. L. 114-5) comme réaction du législateur à cet arrêt.",
    "ou": "Contexte législatif, commentaire de l'arrêt de 2025"
   }
  ],
  "distinguer": "Solution neutralisée par la loi du 4 mars 2002 : à ne pas présenter comme droit positif. À l'époque, l'action des parents était contractuelle ; à l'égard de l'enfant, le visa de l'article 1382 suggère une responsabilité extracontractuelle.",
  "textes": [
   "1165 ancien",
   "1382 ancien"
  ],
