  "numero": "",
  "provenance": [
   "Manuel"
  ],
  "chapitres": [
   17,
   13
  ],
  "notions": [
   "réparation intégrale",
   "obligation de minimiser",
   "faute de la victime",
   "obligation de minimiser le dommage",
   "lien causal"
  ],
  "faits": "Selon le site (deux arrêts du 19 juin 2003), il s'agit de situations où la victime n'a pas adopté la mesure qui aurait limité son dommage (par exemple refus d'une seconde opération).",
  "question": "L'abstention de la victime de limiter son préjudice rompt-elle le lien causal ou constitue-t-elle une faute ?",
  "solution": "Non : refuser des soins ou ne pas relancer son activité n'est pas une faute de nature à réduire l'indemnisation ; la victime n'a pas à minimiser son préjudice dans l'intérêt du responsable.",
  "justifie": [
   {
    "argument": "Refuser toute réduction de l'indemnité au motif que la victime n'a pas pris les mesures pour atténuer son dommage (opération refusée, par exemple).",
    "ou": "Cas pratique : argument du responsable sur la faute de la victime"
   },
   {
    "argument": "Soutenir que le refus d'une opération ou d'un soin n'est pas une faute opposable à la victime et ne réduit pas l'indemnisation.",
    "ou": "Cas pratique (refus de soins)"
   },
   {
    "argument": "Réfuter l'argument du responsable selon lequel la victime aurait dû limiter son préjudice (se soigner, reprendre son activité).",
    "ou": "Cas pratique (évaluation du préjudice) ; faute de la victime"
   }
  ],
  "distinguer": "Solution critiquée par la doctrine ; le projet de 2017 prévoyait une réduction, sauf dommage corporel, mais n'est pas en vigueur.",
