  "faits": "Une mineure, confiée à la tutelle du département de Maine-et-Loire par un juge des tutelles puis placée par un service départemental dans un foyer d'accueil géré par une association, provoque volontairement un incendie dans un immeuble en copropriété lors d'une fugue. La cour d'appel déclare l'association responsable en la qualifiant de gardienne.",
  "question": "Qui répond du fait du mineur placé en foyer par le département tuteur : le foyer ou le département ?",
  "solution": "Le département investi de la tutelle, qui a la charge d'organiser, contrôler et diriger à titre permanent le mode de vie du mineur, est responsable de plein droit tant qu'aucune décision judiciaire n'a suspendu cette mission ; la cour d'appel est cassée sur ce point.",
  "justifie": [
   {
    "argument": "Soutenir que la personne publique ou privée investie de la tutelle répond de plein droit du mineur dont elle organise le mode de vie, même s'il est hébergé en foyer et en fugue.",
    "ou": "Cas pratique : mineur tutélaire placé dans un établissement"
   },
   {
    "argument": "Étendre Blieck aux tuteurs institutionnels.",
    "ou": "Dissertation : domaine de l'art. 1242 al. 1er"
   }
  ],
  "distinguer": "La responsabilité n'est pas fondée sur la garde matérielle du foyer mais sur la charge permanente du mode de vie.",
