  "juridiction": "Ass. plén.",
  "date": "2007-06-29",
  "numero": "06-18.141",
  "provenance": [
   "CM",
   "TD n°6"
  ],
  "chapitres": [
   15,
   13
  ],
  "notions": [
   "association sportive",
   "faute caractérisée",
   "violation des règles du jeu",
   "rugby"
  ],
  "faits": "Lors d'un match de rugby organisé par deux comités régionaux, un adhérent est grièvement blessé lors de la mise en place d'une mêlée. La cour d'appel de renvoi retient la responsabilité des comités en jugeant que l'indétermination des circonstances et l'absence de faute établie sont indifférentes.",
  "question": "La victime d'un dommage sportif doit-elle prouver une faute d'un joueur pour engager la responsabilité du club ?",
  "solution": "Oui : les associations sportives sont responsables des dommages causés par leurs membres lorsque l'un ou plusieurs d'entre eux, même non identifiés, ont commis une faute caractérisée par une violation des règles du jeu. L'arrêt d'appel est cassé pour ne pas avoir relevé une telle faute.",
  "justifie": [
   {
    "argument": "Soutenir que la responsabilité du club suppose une faute caractérisée par une violation des règles du jeu imputable à un ou plusieurs joueurs, même non identifiés ; un simple accident de jeu ne suffit pas.",
    "ou": "TD n°6 : variante « Arthur n'a commis aucune faute » et match amical entre associations"
   },
   {
    "argument": "Refuser le fait causal : le régime des clubs diffère de celui des parents.",
    "ou": "Cas pratique / dissertation : régimes comparés (parents, clubs)"
   }
  ],
  "distinguer": "Ne pas confondre avec Ch. mixte, 29 juin 2007 (autre sujet). Pour les parents, un simple fait causal suffit (Levert, 2001) ; pour les clubs, faute caractérisée.",
  "textes": [
   "1384 al. 1er (aujourd'hui 1242 al. 1er)"
  ],
