  "faits": "Un accident de la circulation implique le véhicule d'un salarié, appartenant à son employeur, et celui d'un autre automobiliste blessé. La victime assigne le salarié conducteur sur le fondement de la loi du 5 juillet 1985. La cour d'appel le condamne, observant qu'il aurait pu appeler son employeur en cause.",
  "question": "L'immunité du préposé joue-t-elle aussi face à l'action fondée sur la loi du 5 juillet 1985 ?",
  "solution": "Oui : le préposé conducteur du véhicule de son commettant, impliqué dans un accident de la circulation, n'est pas tenu à indemnisation à l'égard de la victime s'il a agi dans les limites de sa mission. Cassation.",
  "justifie": [
   {
    "argument": "Soutenir que la victime d'un accident de la circulation ne peut pas agir contre le salarié conducteur resté dans sa mission, mais contre l'employeur (gardien).",
    "ou": "Cas pratique : accident causé par un salarié conduisant le véhicule de l'entreprise"
   },
   {
    "argument": "Étendre l'immunité de Costedoat au régime spécial de la loi de 1985.",
    "ou": "Dissertation : portée de l'immunité"
   }
  ],
  "distinguer": "Même date que l'arrêt du 28 mai 2009 sur le préjudice d'agrément (ch. 17, autre affaire). Voir Damioli (2020) : le préposé n'est pas gardien.",
