  "faits": "Atteinte d'un cancer du col utérin qu'elle imputait à la prise de Distilbène (DES) par sa mère enceinte, une femme a assigné deux laboratoires ayant commercialisé la même molécule sous deux noms. La cour d'appel l'a déboutée au motif qu'aucune preuve n'établissait lequel des deux produits avait été administré.",
  "question": "Quand l'exposition au DES est établie mais que le laboratoire fournisseur est inconnu, à qui incombe la preuve de l'origine du produit ?",
  "solution": "Dès lors qu'il est constaté que le DES a directement causé la pathologie, c'est à chacun des laboratoires de prouver que son produit n'est pas à l'origine du dommage. L'arrêt d'appel est cassé.",
  "justifie": [
   {
    "argument": "Soutenir que la victime exposée in utero au DES n'a pas à identifier le laboratoire fautif : chacun doit prouver que son produit n'est pas en cause.",
    "ou": "Cas pratique (produit commercialisé par plusieurs fabricants) ; causalité alternative"
   },
   {
    "argument": "Utiliser l'arrêt pour illustrer une présomption jurisprudentielle de causalité contre les membres d'un groupe identifié.",
    "ou": "Dissertation sur la preuve du lien de causalité"
   }
  ],
  "distinguer": "Ne pas confondre avec l'arrêt de 2023 (Civ. 1re, 18 oct. 2023), qui traite de la pluralité de causes (cause non exclusive) et non de l'identification du fabricant. Deux arrêts du même jour : n° 08-16305 (Bull. n° 187) et n° 08-10081 (Bull. n° 186).",
