  "question": "Le propriétaire qui confie son animal à un ami pour l'entretien courant en perd-il la garde ?",
  "solution": "Rejet : la garde de la jument est restée à la propriétaire, car l'amie, chargée seulement de l'entretien courant (nourriture, soins quotidiens, promenades), n'avait reçu ni pouvoir de contrôle ni pouvoir de direction.",
