  "faits": "Une maison de retraite héberge un résident en vertu d'un contrat ; un dommage causé par ce résident à un tiers est invoqué contre l'établissement (faits précis non connus avec certitude).",
  "question": "Un établissement qui héberge une personne en vertu d'un contrat répond-il de plein droit du fait de celle-ci sur le fondement de l'art. 1242 al. 1er ?",
  "solution": "Non, selon le site : le pouvoir d'organiser et de contrôler à titre permanent le mode de vie doit résulter d'une décision judiciaire ou administrative, non d'un simple contrat ; la responsabilité fondée sur Blieck ne joue donc pas.",
  "justifie": [
   {
    "argument": "Refuser Blieck à un établissement privé dont le pouvoir sur le résident résulte seulement d'un contrat.",
    "ou": "Cas pratique : résident d'une maison de retraite ou d'un établissement d'hébergement"
   },
   {
    "argument": "Rattacher l'al. 1er au pouvoir d'origine judiciaire ou administrative, pas contractuelle.",
    "ou": "Dissertation : domaine du principe général du fait d'autrui"
   }
  ],
  "distinguer": "Opposer aux foyers éducatifs ou centres d'aide par le travail dont la mission découle d'une décision (Blieck, 6 juin 2002).",
