  "question": "Un préjudice écologique pur est-il réparable, malgré l'exigence d'un préjudice personnel ?",
  "solution": "La chambre criminelle a indemnisé des collectivités territoriales titulaires d'une compétence environnementale, ce qui préservait le caractère personnel du préjudice. La loi du 8 août 2016 a ensuite consacré le préjudice écologique aux articles 1246 à 1252.",
