  "nom": "PPR / Gucci, « L'empire menacé »",
  "juridiction": "Civ. 1re",
  "date": "2014-07-02",
  "numero": "13-16730",
  "provenance": [
   "CM"
  ],
  "chapitres": [
   13
  ],
  "notions": [
   "liberté d'expression",
   "dénigrement",
   "droit commun"
  ],
  "faits": "Un éditeur publie un livre exprimant des doutes sur la capacité financière du groupe PPR à racheter ses actions Gucci, et la couverture est affichée sur un espace publicitaire en ligne. Après l'échec d'une procédure pénale, PPR demande réparation sur le terrain de la faute ; elle est déboutée.",
  "question": "L'atteinte à l'image d'une entreprise par des propos écrits relève-t-elle de l'article 1382 ?",
  "solution": "Rejet du pourvoi : hors restriction légalement prévue, la liberté d'expression est un droit dont l'exercice, sauf dénigrement de produits ou services, ne peut être contesté sur le fondement de l'article 1382. L'auteur n'ayant pas méconnu l'article 10 § 2 de la CEDH, la cour d'appel a légalement justifié sa décision.",
  "justifie": [
   {
    "argument": "Soutenir que l'exercice de la liberté d'expression n'est sanctionnable sur le fondement de l'article 1240 que dans les cas prévus par la loi, à l'exception du dénigrement de produits ou services.",
    "ou": "Cas pratique (critique publiée, avis, article) ; dissertation"
   },
   {
    "argument": "Relever que l'opinion, même subjective ou peu rigoureuse, ne constitue pas une faute si les informations ne sont ni fausses ni trompeuses.",
    "ou": "Cas pratique ; commentaire"
   }
  ],
  "distinguer": "Ne pas oublier l'exception du dénigrement de produits ou services (Civ. 1re, 8 avr. 2008 ; 27 nov. 2013).",
  "textes": [
   "1240 (anc. 1382)",
   "10 CEDH"
  ],
  "td_fiche": false,
