  "faits": "Un homme agressé dans une rame de métro a poursuivi son agresseur sur le quai, qui l'a repoussé : il est tombé sur la voie et est mort quand la rame a redémarré. Le FGTI, qui avait indemnisé les parents, a agi contre la RATP, gardienne de la rame.",
