  "faits": "Sur un quai de RER, un homme a été soudainement ceinturé et entraîné sur les voies par un tiers qui souffrait de schizophrénie, juste avant l'arrivée d'un train ; ils ont été tués. Le FGTI, qui avait indemnisé les ayants droit, a agi contre la SNCF.",
  "question": "Le fait d'un tiers agresseur constitue-t-il pour la SNCF, gardienne du train, une force majeure ?",
  "solution": "La cour d'appel a pu estimer, sans inverser la charge de la preuve, que le fait du tiers présentait un caractère imprévisible et irrésistible : agression brutale, aucune mesure de surveillance ni installation n'aurait permis de l'empêcher, sauf à poser des façades de quai dans toutes les gares, ce qui ne pouvait être exigé de la SNCF. Force majeure admise ; rejet.",
  "justifie": [
   {
    "argument": "Soutenir que l'agression soudaine d'un tiers dont aucune mesure raisonnable ne pouvait empêcher la réalisation est une force majeure exonérant totalement le gardien.",
    "ou": "Cas pratique (fait du tiers, transports)"
   },
   {
    "argument": "Écarter le grief d'inversion de la charge de la preuve : le gardien prouve les circonstances, le juge apprécie l'irrésistibilité.",
    "ou": "Cas pratique, commentaire"
   }
  ],
  "distinguer": "À comparer avec 16-26198 (même jour), qui casse faute de motivation : la force majeure se juge in concreto, pas par principe.",
