  "juridiction": "Civ. 2e",
  "date": "2020-01-16",
  "numero": "19-10.489",
  "provenance": [
   "CM"
  ],
  "chapitres": [
   14,
   15
  ],
  "notions": [
   "garde",
   "préposé",
   "incompatibilité",
   "fait des choses"
  ],
  "faits": "Un salarié est victime d'un accident de la circulation après être sorti du véhicule de son employeur, la société Damioli ; il est percuté par un véhicule d'une autre société. L'assureur de cette dernière appelle en garantie l'assureur de Damioli. La cour d'appel retient que la garde du camion avait été transférée au chauffeur.",
  "question": "Un salarié qui conduit le véhicule de son employeur peut-il en être le gardien ?",
  "solution": "Non : la garde étant alternative et non cumulative, les qualités de gardien et de préposé sont incompatibles. Le salarié agissant comme préposé, c'est l'employeur qui reste gardien ; l'arrêt est cassé sur ce point.",
  "justifie": [
   {
    "argument": "Soutenir que le préposé qui utilise la chose de son commettant dans ses fonctions n'en est pas le gardien : le commettant en reste gardien.",
    "ou": "Cas pratique : dommage causé par une chose confiée à un salarié"
   },
   {
    "argument": "Articuler fait des choses (art. 1242 al. 1er) et fait du préposé (al. 5) en identifiant le véritable responsable.",
    "ou": "Cas pratique : choix du fondement (garde ou commettant)"
   }
  ],
  "distinguer": "À ne pas confondre avec le transfert de garde conventionnel entre non-préposés ; ici le lien de préposition exclut le transfert.",
  "textes": [
   "1242 al. 1er et 5 (ancien 1384)"
  ],
  "td_fiche": false,
