  "notions": [
   "préjudice d'attente et d'inquiétude",
   "victime par ricochet",
   "préjudice d'affection"
  ],
  "faits": "À la suite du décès d'une femme tuée lors d'un attentat en 2016, sa fille et les deux filles mineures de celle-ci reçoivent une indemnité pour préjudice d'affection et une autre pour attente et inquiétude. Le FGTI conteste la seconde.",
  "question": "Le préjudice d'attente et d'inquiétude des proches se confond-il avec le préjudice d'affection ?",
  "solution": "Non : l'angoisse née de l'attente et de l'incertitude, entre la découverte de l'événement et la connaissance de son issue, est un préjudice spécifique des victimes par ricochet, indemnisé de façon autonome lorsque la victime directe a subi une atteinte grave ou est décédée.",
  "justifie": [
   {
    "argument": "Soutenir que les proches ont droit à une indemnité distincte pour la période d'angoisse précédant la connaissance du sort de la victime.",
    "ou": "Cas pratique (événement collectif, attentat, catastrophe), victimes par ricochet"
   },
   {
    "argument": "Écarter l'objection de double indemnisation en montrant que ce poste est distinct du préjudice d'affection.",
    "ou": "Argumentation en défense ou en demande"
   }
  ],
  "distinguer": "Il vise l'attente avant de connaître l'issue de l'événement ; il ne couvre pas la crainte durable d'un proche exposé à un risque de maladie (cas de l'amiante, Distilbène).",
