  "solution": "Rejet : le propriétaire peut conserver la garde de la structure du véhicule lorsque l'accident vient d'un défaut de celui-ci, sauf s'il a averti le tiers ; il est donc tenu d'indemniser la victime au titre de la loi du 5 juillet 1985.",
