  "faits": "Un invité chute sur un passage enneigé et verglacé dans l'enceinte d'une société, où il se rendait à une réception. La société avait déneigé un autre accès, mais pas celui emprunté.",
  "question": "La neige et le verglas, choses sans maître, empêchent-ils d'engager la responsabilité du propriétaire du sol ?",
  "solution": "Rejet : la société est gardienne du sol de sa propriété ; ce sol, chose inerte normalement en position normale pour le passage, est en position anormale lorsqu'il est rendu dangereux et glissant par les intempéries. Sa responsabilité est engagée.",
  "justifie": [
   {
    "argument": "Soutenir que le propriétaire d'un sol recouvert de neige ou de verglas en répond comme gardien du sol, la res nullius ne le protégeant pas.",
    "ou": "Cas pratique : chute sur sol glissant dans une propriété."
   },
   {
    "argument": "Montrer que l'anormalité du sol s'apprécie au regard de sa destination fonctionnelle (passage de piétons).",
    "ou": "Chose inerte : critère de l'anormalité."
   }
  ],
  "distinguer": "Solution exceptionnelle pour une res nullius : le gardien est celui du sol, non de la neige.",
