  "question": "L'appauvri qui échoue à prouver un prêt peut-il se rabattre sur l'enrichissement injustifié ?",
  "solution": "Non : l'absence de preuve du prêt est un obstacle de droit au sens de l'art. 1303-3 ; l'action fondée sur l'enrichissement injustifié ne peut suppléer la carence probatoire du prêteur. Pourvoi rejeté ; confirmation de la solution de Civ. 1re, 2 avr. 2009.",
