  "faits": "Une SCI achète en 2008 un ensemble immobilier destiné à des bureaux, mais ne peut obtenir de permis de construire. Elle assigne le notaire, dont le manquement au devoir de conseil est admis ; la cour d'appel de renvoi rejette ses demandes car elles n'ont pas été fondées sur la perte de chance de renoncer à l'acquisition.",
  "question": "Le juge qui constate une perte de chance peut-il refuser de l'indemniser faute de demande fondée sur ce terrain ?",
  "solution": "Non : même solution que dans l'arrêt Unipatis du même jour. Le juge peut rechercher une perte de chance d'éviter le dommage et ne peut refuser de l'indemniser en se fondant sur le fait que seule la réparation intégrale lui a été demandée. Cassation.",
  "justifie": [
   {
    "argument": "Soutenir qu'un client privé par la faute du notaire de la possibilité de renoncer à son acquisition peut obtenir la réparation de cette chance perdue, même si elle n'a pas été demandée expressément.",
    "ou": "Cas pratique (responsabilité des professionnels du droit), perte de chance"
   },
   {
    "argument": "Citer l'arrêt avec Unipatis pour montrer que la solution est de principe et confirmée le même jour.",
    "ou": "Dissertation ou commentaire"
   }
  ],
  "distinguer": "Même solution que Unipatis (n° 22-21.812) ; la présente affaire a déjà donné lieu à une cassation (Civ. 1re 30 juin 2021, n° 20-10.472).",
