  "faits": "Une femme exposée in utero au Distilbène (DES) agit contre le laboratoire producteur. La cour d'appel de renvoi rejette sa demande d'indemnisation de l'anxiété, faute de preuve qu'elle vit dans une inquiétude permanente.",
  "question": "L'anxiété née de l'exposition à un risque élevé de pathologie grave est-elle indemnisable, et que doit prouver la victime ?",
  "solution": "Constitue un préjudice indemnisable l'anxiété résultant de l'exposition à un risque élevé de développer une pathologie grave ; ce préjudice est caractérisé par la seule connaissance de ce risque par la victime. Cassation sur ce point.",
